def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marker = min(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    # Fill background cells lying between marker cells in any row or column.
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == marker]
        if len(cs) >= 2:
            for c in range(min(cs), max(cs) + 1):
                if grid[r][c] != marker:
                    out[r][c] = 3
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] == marker]
        if len(rs) >= 2:
            for r in range(min(rs), max(rs) + 1):
                if grid[r][c] != marker:
                    out[r][c] = 3
    return out
